
INSERT INTO public.past_questions (subject_id, level, exam_month, exam_year, paper, question_number, marks, question_text, topic_tags, difficulty) VALUES
('cd1b92d9-8dc9-4a50-a677-4936f842c1ab','Foundation','June',2024,'Paper 1','1(a)',5,'A and B are partners sharing profits in the ratio 3:2. They admit C for 1/5th share. C brings ₹50,000 as capital but is unable to bring his share of goodwill of ₹20,000 in cash. Pass the necessary journal entries assuming goodwill does not appear in the books.', ARRAY['Partnership','Admission','Goodwill'],'medium'),
('8c581379-6366-44ba-afc9-dedea14477ac','Foundation','June',2024,'Paper 2','3(b)',4,'Explain the doctrine of "Caveat Emptor" under the Sale of Goods Act, 1930 and state any three exceptions to it.', ARRAY['Sale of Goods Act','Caveat Emptor'],'easy'),

('15d8ad21-2edd-42bf-832f-8b1790df1575','Intermediate','May',2024,'Paper 1','2',10,'X Ltd. acquired 80% equity shares of Y Ltd. on 1st April 2023 for ₹16,00,000. The net assets of Y Ltd. on the date of acquisition stood at ₹15,00,000. During the year, Y Ltd. earned a profit of ₹3,00,000 and paid a dividend of ₹1,00,000. Compute Goodwill / Capital Reserve on acquisition and Minority Interest as on 31st March 2024 as per AS 21.', ARRAY['AS 21','Consolidation','Goodwill','Minority Interest'],'hard'),
('4a427d15-2b2d-466b-ae80-707c3c6359b6','Intermediate','May',2024,'Paper 3','1(a)',8,'A factory produces a single product. The selling price is ₹100 per unit. Variable cost per unit is ₹60 and fixed cost for the year is ₹4,00,000. Calculate: (i) BEP in units and value (ii) Margin of Safety if actual sales are 15,000 units (iii) Sales required to earn a profit of ₹2,00,000 (iv) New BEP if selling price is reduced by 10%.', ARRAY['Marginal Costing','BEP','Margin of Safety'],'medium'),
('e03c8bdb-a3ef-479c-bd6c-cc370ea640ec','Intermediate','May',2024,'Paper 4','5(b)',6,'Mr. Raj, a resident individual aged 45 years, has the following income for the PY 2023-24: Salary ₹8,00,000; Income from house property ₹1,50,000; LTCG on listed equity shares (STT paid) ₹1,80,000; Interest on savings bank ₹15,000. Compute his total income and tax liability under the default new tax regime u/s 115BAC for AY 2024-25.', ARRAY['Income Tax','115BAC','LTCG','Computation'],'hard'),
('13b653d1-19fd-4f9b-92bb-8331c35af90e','Intermediate','May',2024,'Paper 2','4(a)',6,'Explain the provisions of Section 149 of the Companies Act, 2013 regarding appointment of Independent Directors. State the conditions a person must satisfy to be appointed as an Independent Director.', ARRAY['Companies Act 2013','Section 149','Independent Director'],'medium'),
('2e70e531-442e-45fe-868c-11e6d177aceb','Intermediate','November',2023,'Paper 6','3',10,'A Ltd. is considering a project requiring an initial investment of ₹20,00,000. The project is expected to generate annual cash inflows of ₹6,00,000 for 5 years. The cost of capital is 12%. Calculate: (i) NPV (ii) IRR (iii) Payback Period (iv) Discounted Payback Period. Advise whether the project should be accepted.', ARRAY['Capital Budgeting','NPV','IRR','Payback'],'medium'),
('f91f9059-472b-4e78-893b-71bacb27208b','Intermediate','November',2023,'Paper 5','2(a)',5,'Define "True and Fair View" in the context of financial statements. What are the key considerations an auditor should keep in mind while forming an opinion on whether the financial statements give a true and fair view?', ARRAY['Auditing','True and Fair','SA 700'],'medium'),

('396d6c97-1896-4455-847e-b491ae4fdab2','Final','May',2024,'Paper 1','1',14,'PQR Ltd. issued 10,000, 10% Debentures of ₹100 each at par on 1st April 2023, redeemable at a premium of 10% at the end of 5 years. Transaction costs were ₹50,000. Compute the effective interest rate and prepare the amortization table for the first 2 years as per Ind AS 109. Pass journal entries for the first year.', ARRAY['Ind AS 109','EIR','Debentures','Amortised Cost'],'hard'),
('471e6620-c672-4071-8f45-c6f1d517ce40','Final','May',2024,'Paper 4','3(a)',8,'Discuss the concept of "Place of Effective Management (POEM)" under section 6(3) of the Income Tax Act, 1961 for determining residential status of a foreign company. Explain the guiding principles issued by CBDT in this regard.', ARRAY['POEM','Section 6(3)','International Tax','Residential Status'],'hard'),
('97154e3b-9276-4edf-8d8f-8176261353ac','Final','May',2024,'Paper 5','2',10,'M/s ABC, a registered person under GST, supplied goods worth ₹10,00,000 (excluding GST @ 18%) to M/s XYZ on 5th April 2024. Tax invoice was issued on 10th April 2024. Payment was received on 25th May 2024. Determine the time of supply, due date for issue of invoice, and the tax period in which the supplier must pay GST. Also state the consequences if invoice is issued late.', ARRAY['GST','Time of Supply','Section 12','CGST Act'],'medium'),
('d1b5ccbb-10eb-40ce-9e9e-c27bca788d19','Final','November',2023,'Paper 3','4(b)',6,'During the audit of XYZ Ltd., the auditor identifies a material uncertainty related to going concern. Discuss the auditor''s reporting responsibilities under SA 570 (Revised) — both when management has made adequate disclosure and when disclosure is inadequate.', ARRAY['SA 570','Going Concern','Audit Report'],'hard'),
('7d824c83-57d3-43a9-aded-216dfae5717a','Final','November',2023,'Paper 2','5(a)',8,'A US-based company has entered into a forward contract to buy ₹5 crore at a rate of ₹83/USD for delivery 3 months later. Spot rate is ₹82.50/USD. 3-month interest rates are 5.5% p.a. in India and 5% p.a. in USA. Determine whether arbitrage opportunity exists. If yes, demonstrate how an arbitrageur can profit with USD 1,00,000.', ARRAY['Forex','Interest Rate Parity','Arbitrage','AFM'],'hard');
